import { test } from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { Survival } from "./survival.js";
import { makeStack } from "./inventory.js";
import { JavaRandom } from "./java-random.js";
import { mobThornsOnPlayerHit } from "./thorns-live.js";

// public/research/thorns-wear-reference.json: tools/probes/ThornsWearProbe.java (regenerated by tools/verify-thorns-wear.mjs) ran
// EnchantmentHelper.func_151384_a on the unchanged 1.7.10 classes for Thorns I-III x Unbreaking 0-III, for a mob, a survival player and a Creative player.
const reference = JSON.parse(await readFile(new URL("../public/research/thorns-wear-reference.json", import.meta.url)));
const PORT_MATERIAL = [0, 1, 2, 4, 3];
const ench = (pairs) => (pairs.length ? pairs.map(([id, lvl]) => ({ id, lvl })) : undefined);
const native = (s) => s && { id: s[0], damage: s[1], count: 1, ...(s[2].length ? { enchantments: ench(s[2]) } : {}) };
function port(s) {
  if (!s) return null;
  const id = 400 + PORT_MATERIAL[(s[0] - 298) >> 2] * 4 + ((s[0] - 298) & 3);
  return makeStack(id, 1, s[1], undefined, s[2].length ? { enchantments: ench(s[2]) } : {});
}

test("the reference is the unchanged 1.7.10 client", () => {
  assert.equal(reference.clientSha1, "e80d9b3bf5085002218d4be59e668bac718abbc6");
  assert.ok(reference.rows.length >= 2500);
});

test("Thorns armour wear with Unbreaking replays natively for a survival player, a Creative player and a mob", () => {
  const seen = { hit: 0, miss: 0, breaks: 0, skipped: 0, unbreaking: {} };
  for (const [kind, thorns, unb, before, seed, attacker, broken, after, next] of reference.rows) {
    const row = JSON.stringify([kind, thorns, unb, before, seed]);
    const random = new JavaRandom(BigInt(seed)), got = [];
    const hurt = (d) => got.push(["thorns", d]), sound = () => got.push(["damage.thorns", 0.5, 1]);
    let armour, rngNext;
    if (kind === "mob") {
      // The probe's mob array is held, boots, leggings, chestplate, helmet; the mob owns native stacks.
      const mob = { equipment: before.map(native) };
      mobThornsOnPlayerHit(mob, random, { hurt, sound });
      armour = mob.equipment.map((s, i) => [s, i]);
      rngNext = random.nextInt();
      before.forEach((b, i) => {
        const live = mob.equipment[i];
        if (after[i] === null) return assert.equal(live, null, row);
        if (live === null) { assert.equal(after[i][1], 0, "a broken stack is natively reset: " + row); seen.breaks++; return; }
        assert.equal(live.damage, after[i][1], "slot " + i + " " + row);
      });
    } else {
      const s = new Survival({}, kind === "creative" ? "creative" : "survival");
      before.forEach((b, i) => { s.inventory.armor[i] = port(b); });
      s.inventory.random = random;
      s.thorns({ hurt, sound });
      rngNext = s.inventory.random.nextInt();
      before.forEach((b, i) => {
        const live = s.inventory.armor[i];
        if (after[i] === null) return assert.equal(live, null, row);
        if (live === null) { assert.equal(after[i][1], 0, "a broken piece is natively reset: " + row); seen.breaks++; return; }
        assert.equal(live.damage, after[i][1], "armour slot " + i + " " + row);
      });
    }
    assert.deepEqual(got, attacker, row);
    assert.equal(rngNext, next, "the wearer's Random is at the native position: " + row);
    assert.equal(broken.length, kind === "creative" ? 0 : broken.length);
    if (attacker.length) seen.hit++; else seen.miss++;
    if (kind !== "creative" && unb > 0) seen.unbreaking[unb] = (seen.unbreaking[unb] ?? 0) + 1;
  }
  assert.ok(seen.hit > 500 && seen.miss > 500 && seen.breaks > 100 && Object.keys(seen.unbreaking).length === 3, JSON.stringify(seen));
});

test("native keeps a broken Thorns piece as a zero-size stack that keeps rolling (probed); the port removes it (pinned difference)", () => {
  assert.equal(reference.ghosts.length, 36);
  let rolled = 0;
  for (const [kind, , , , , first, wearerLog, , second] of reference.ghosts) {
    assert.deepEqual(first, [0, 0], kind + ": stackSize 0, damage reset, still in the slot");
    assert.deepEqual(wearerLog, ["broken"]);
    assert.ok(second[0] === 0 && (second[1] === 1 || second[1] === 3), "the empty stack is worn again by the second reaction: " + JSON.stringify(second));
    rolled++;
  }
  assert.equal(rolled, 36);
  const mob = { equipment: [null, null, null, { id: 299, count: 1, damage: 528, enchantments: [{ id: 7, lvl: 1 }] }, null] };
  mobThornsOnPlayerHit(mob, new JavaRandom(5n), { hurt() {}, sound() {} });
  assert.equal(mob.equipment[3], null, "the port empties the slot where the original keeps the zero-size stack");
});
